mapper.select:
SELECT sf.type AS `key`, COUNT(*) AS `value` FROM sys_item_file sif JOIN sys_file sf ON sif.file_id = sf.id WHERE sif.item_id IN
#{itemId}
GROUP BY sf.type

SELECT sif.* FROM sys_item_file sif JOIN sys_dataset_item sdi ON sif.item_id = sdi.id WHERE sdi.dataset_id IN
#{datasetId}
ORDER BY sdi.dataset_id, sif.item_id, sif.type
